<?php
require_once '../includes/funcoes.php';exigir_admin();if(isset($_GET['excluir'])){$pdo->prepare("DELETE FROM categorias WHERE id=?")->execute([(int)$_GET['excluir']]);log_acao('Categoria excluída');header('Location: categorias.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && trim($_POST['nome']??'')){ $pdo->prepare("INSERT INTO categorias(nome) VALUES(?)")->execute([trim($_POST['nome'])]);log_acao('Categoria cadastrada');header('Location: categorias.php');exit;}
$rows=$pdo->query("SELECT * FROM categorias ORDER BY nome")->fetchAll();$titulo='Categorias';require '../includes/header.php';?>
<div class="admin-shell"><?php require '_menu.php';?><section><h1 class="section-title">Categorias</h1><div class="panel mb-3"><form method="post" class="d-flex gap-2"><input class="form-control" name="nome" placeholder="Nova categoria" required><button class="btn btn-lumia">Adicionar</button></form></div><div class="panel"><table class="table datatable"><thead><tr><th>Categoria</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nome'])?></td><td><a class="text-danger" data-confirm="Excluir categoria?" href="?excluir=<?=$r['id']?>">Excluir</a></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require '../includes/footer.php';?>
